using ClipBridge;
sealed partial class BridgeWindow
{
    private readonly Dictionary<string,Label> groupViews=[];
    private GroupIdentity LocalGroupIdentity(){if(data.GroupIdentity is null){data.GroupIdentity=GroupIdentity.Create(data.Identity,Environment.MachineName);Save();}return data.GroupIdentity;}
    private void OpenGroups(){selectedPage=1;dashboardStructure="";RenderPage();}
    private async Task GroupLoop(){while(!stop.IsCancellationRequested){try{if(!paused&&data.GroupIdentity is{} identity){bool changed=false;foreach(var group in data.Groups.ToList()){try{if(await GroupRuntime.Refresh(group,identity,stop.Token)){Save();changed=true;}}catch(OperationCanceledException)when(stop.IsCancellationRequested){throw;}catch{group.Status="成员信息暂不可用，稍后重试";group.CheckedAt=DateTimeOffset.UtcNow.ToUnixTimeSeconds();Save();changed=true;}}if(changed)ApplyGroupChannels();}}catch(OperationCanceledException){break;}catch{status.Text="同步组状态暂不可用";}try{await Task.Delay(2000,stop.Token);}catch(OperationCanceledException){break;}}}
    private void ApplyGroupChannels(){if(data.GroupIdentity is null)return;var desired=data.Groups.SelectMany(g=>GroupRuntime.Channels(g,data.GroupIdentity)).ToDictionary(p=>p.Config.Pair);bool changed=false;
        foreach(var old in data.Profiles.Where(p=>p.GroupId.Length>0&&!desired.ContainsKey(p.Config.Pair)).ToList()){old.Enabled=false;old.State.Pending=null;data.Tombstones[old.Config.Pair]=old.State;data.Profiles.Remove(old);hub.RemoveRoute(old.Config.Pair);changed=true;}
        foreach(var route in desired.Values){var old=data.Profiles.FirstOrDefault(p=>p.Config.Pair==route.Config.Pair);if(old is not null){if(old.Config!=route.Config)throw new System.Security.Cryptography.CryptographicException("同步组连接密钥发生变化");continue;}if(data.Profiles.Count>=16){data.Groups.First(g=>g.Id==route.GroupId).Status="同步通道已达上限，请移除不再使用的同步组";continue;}route.State=data.Tombstones.GetValueOrDefault(route.Config.Pair)??new();route.State.Pending=null;data.Profiles.Add(route);changed=true;}
        if(changed){Save();if(started)Reconcile();dashboardStructure="";RenderPage();}
    }
    private void CopyGroupInvitation(string text){Clipboard.SetText(text);suppressedSequence=GetClipboardSequenceNumber();lastObserved=text;}
    private void OpenGroupWizard(bool joining,DeviceGroup? existing=null,GroupConnection? seed=null){try{var identity=LocalGroupIdentity();using var wizard=new GroupWizard(identity,joining,existing,async(name,connection,setup,ct)=>{if(data.Groups.Count>=4)throw new InvalidOperationException("最多保存 4 个同步组");var group=Groups.Create(identity,name,connection);await GroupStore.Provision(group,setup,ct);using(var store=new GroupStore(group))await store.Publish(identity,ct);data.Groups.Add(group);Save();return group;},Save,group=>{if(data.Groups.Any(g=>g.Id==group.Id)){var known=data.Groups.First(g=>g.Id==group.Id);if(Groups.CertificateHash(known.Root)!=Groups.CertificateHash(group.Root))throw new System.Security.Cryptography.CryptographicException("同步组身份不一致");group=Groups.Install(known,group,identity);data.Groups.Remove(known);data.Groups.Add(group);Save();return;}if(data.Groups.Count>=4)throw new InvalidOperationException("最多保存 4 个同步组");data.Groups.Add(Groups.Install(null,group,identity));Save();},CopyGroupInvitation);if(seed is not null)wizard.Prefill(seed);wizard.ShowDialog(this);ApplyGroupChannels();dashboardStructure="";RenderPage();}catch(Exception e){MessageBox.Show(this,e is ArgumentException or InvalidOperationException?e.Message:"无法处理同步组，请检查本地数据。","ClipBridge");}}
    private async Task RemoveGroupMember(DeviceGroup group,string member){if(MessageBox.Show(this,"将此设备移出同步组？其他设备收到移出通知后将停止向它发送新内容。其他配对不受影响。","ClipBridge",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;try{Groups.Remove(group,LocalGroupIdentity(),member);if(member==data.Identity)group.Enabled=false;Save();ApplyGroupChannels();using var store=new GroupStore(group);await store.Publish(LocalGroupIdentity(),stop.Token);Save();dashboardStructure="";RenderPage();}catch{group.Status="本机已应用移出操作，等待通知其他成员";Save();}}
    private IEnumerable<IGrouping<string,BridgeProfile>> LegacyGroups()=>data.Profiles.Where(p=>p.GroupId.Length==0).GroupBy(p=>p.Group);
    private void SetGroupEnabled(DeviceGroup group,bool enabled){group.Enabled=enabled;Save();ApplyGroupChannels();Reconcile();dashboardStructure="";RenderPage();}
    private void DeleteLegacyGroup(string id){var rows=LegacyGroups().FirstOrDefault(g=>g.Key==id)?.ToList();if(rows is null)return;if(MessageBox.Show(this,"删除这个双设备同步组？仅删除本机连接。","ClipBridge",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;foreach(var p in rows){p.Enabled=false;p.State.Pending=null;data.Tombstones[p.Config.Pair]=p.State;hub.RemoveRoute(p.Config.Pair);data.Profiles.Remove(p);string old=Path.Combine(folder,"profiles",p.Config.Pair,"config.bin");if(File.Exists(old))File.Delete(old);}Save();Reconcile();dashboardStructure="";RenderPage();}
    private void BuildGroupsPage(int width){groupViews.Clear();var actions=new FlowLayoutPanel{Height=54,WrapContents=false};foreach(var entry in new[]{("创建同步组",false),("加入同步组",true)}){bool joining=entry.Item2;var button=MakeButton(entry.Item1,!joining);button.Size=new Size(150,44);button.Click+=(_,_)=>OpenGroupWizard(joining);actions.Controls.Add(button);}AddBlock(actions);
        foreach(var group in data.Groups){var members=group.Members.Values.Where(c=>!group.Removed.Contains(c.Member.Id)).ToList();bool left=group.Removed.Contains(data.Identity);var card=new SoftPanel{Width=width,Height=205+members.Count*49};var name=MakeLabel(group.Name,16,FontStyle.Bold);name.AutoSize=false;name.AutoEllipsis=true;name.SetBounds(22,18,width-125,40);name.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;card.Controls.Add(name);
            var toggle=new PillSwitch{AccessibleName="开启同步组："+group.Name,Checked=group.Enabled&&!left,Enabled=!left};toggle.SetBounds(width-78,23,54,30);toggle.Anchor=AnchorStyles.Top|AnchorStyles.Right;toggle.CheckedChanged+=(_,_)=>SetGroupEnabled(group,toggle.Checked);card.Controls.Add(toggle);
            var detail=MakeLabel("",9);detail.AutoSize=false;detail.SetBounds(22,63,width-44,44);detail.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;detail.ForeColor=AppStyle.Muted;card.Controls.Add(detail);groupViews[group.Id]=detail;
            int y=119;foreach(var certificate in members){var member=certificate.Member;var label=MakeLabel(member.Name+(member.Id==data.Identity?"（本机）":""),10);label.AutoSize=false;label.AutoEllipsis=true;label.SetBounds(22,y,width-230,35);label.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;card.Controls.Add(label);
                if(member.Id!=data.Identity&&group.SuppressedPeers.Contains(member.Id)){var reconnect=MakeButton("恢复同步",false);reconnect.SetBounds(width-205,y-3,95,36);reconnect.Anchor=AnchorStyles.Top|AnchorStyles.Right;reconnect.Click+=(_,_)=>{group.SuppressedPeers.Remove(member.Id);Save();ApplyGroupChannels();dashboardStructure="";RenderPage();};card.Controls.Add(reconnect);}
                var remove=MakeButton(member.Id==data.Identity?"退出":"移出",false);remove.SetBounds(width-104,y-3,82,36);remove.Anchor=AnchorStyles.Top|AnchorStyles.Right;remove.Click+=async(_,_)=>await RemoveGroupMember(group,member.Id);card.Controls.Add(remove);y+=49;}
            var invite=MakeButton(left?"删除本机记录":"邀请设备",true);invite.SetBounds(22,y,140,40);invite.Enabled=left||group.Enabled;invite.Click+=(_,_)=>{if(left){if(MessageBox.Show(this,"仅删除本机记录；未收到退出通知的其他设备需手动移除此设备。","ClipBridge",MessageBoxButtons.YesNo)==DialogResult.Yes){data.Groups.Remove(group);Save();ApplyGroupChannels();dashboardStructure="";RenderPage();}}else OpenGroupWizard(false,group);};card.Controls.Add(invite);
            var refresh=MakeButton("刷新成员",false);refresh.SetBounds(174,y,140,40);refresh.Click+=async(_,_)=>{try{await GroupRuntime.Refresh(group,LocalGroupIdentity(),stop.Token,true);Save();ApplyGroupChannels();dashboardStructure="";RenderPage();}catch{MessageBox.Show(this,"成员更新失败，请检查网络或服务商限频。");}};card.Controls.Add(refresh);AddBlock(card);}
        foreach(var legacy in LegacyGroups().ToList()){string key=legacy.Key;var rows=legacy.ToList();var first=rows[0];var card=new SoftPanel{Width=width,Height=190};var title=MakeLabel(first.Title,15,FontStyle.Bold);title.AutoSize=false;title.AutoEllipsis=true;title.SetBounds(22,18,width-124,38);title.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;card.Controls.Add(title);var toggle=new PillSwitch{AccessibleName="开启双设备同步组",Checked=rows.Any(p=>p.Enabled)};toggle.SetBounds(width-78,22,54,30);toggle.Anchor=AnchorStyles.Top|AnchorStyles.Right;toggle.CheckedChanged+=(_,_)=>{foreach(var p in rows){p.Enabled=toggle.Checked;if(!p.Enabled)p.State.Pending=null;}Save();Reconcile();dashboardStructure="";RenderPage();};card.Controls.Add(toggle);
            var text=MakeLabel("双设备组 · 保留早期配对\n需要添加更多设备时，双方更新后重新建组。",10);text.AutoSize=false;text.SetBounds(22,62,width-44,62);text.ForeColor=AppStyle.Muted;card.Controls.Add(text);var rebuild=MakeButton("重新建组",false);rebuild.SetBounds(22,133,140,40);rebuild.Click+=(_,_)=>OpenGroupWizard(false,seed:new(){Transport=first.Config.Transport,Server=first.Config.Server,Username=first.Config.Username,Password=first.Config.Password});card.Controls.Add(rebuild);var remove=MakeButton("删除组",false);remove.SetBounds(174,133,110,40);remove.Click+=(_,_)=>DeleteLegacyGroup(key);card.Controls.Add(remove);AddBlock(card);}
        if(data.Groups.Count==0&&!LegacyGroups().Any()){var empty=MakeLabel("尚无同步组。创建一个，或加入已有组。",12);empty.Height=60;AddBlock(empty);}
    }
}
